# -*- coding: utf-8 -*-
"""Текстовый выпуск 4 (план E005): тело страницы lessons/ep04.html.

Собирается tools/build.py: build импортирует этот модуль и вызывает render().
Части разделены маркером <!--AFTER-TICKETS-->: всё после него сайт показывает под билетами.
Картинки (lessons/ep04/*.png) build берёт из этой папки или из content/assets/signs."""
from pdd.lessonkit import chat, lq, fig, gl, signrow
from figs import fig_crossing_zebra, fig_crossing_signs, fig_railway, fig_levels, fig_town

IMG = "lessons/ep04/"
SIGNS = [("sign_5_19_1", "5.19.1", "Пешеходный переход (справа)"), ("sign_5_19_2", "5.19.2", "Пешеходный переход (слева)"),
         ("sign_1_23", "1.23", "Предупреждает о переходе"), ("sign_1_1", "1.1", "Переезд со шлагбаумом"),
         ("sign_1_2", "1.2", "Переезд без шлагбаума"), ("sign_5_23_2", "5.23.2", "Начало застроенного участка"),
         ("sign_5_24_2", "5.24.2", "Его конец")]
SIGNS_CAPTION = ("Рисунки знаков — из приложения 1 к закону (Matsne). Для 5.23.1, 5.25 и 5.26 в приложении вместо рисунка "
                 "пример с названием города («Сурами», «Оками»), поэтому их здесь нет.")


P = []
P.append(chat(
    ("a", "В прошлый раз остановились на трёх словах: переход, переезд, населённый пункт. По-моему, это самое простое в курсе."),
    ("m", "Переход — где зебра. Переезд — где поезд. Город — где дома. Пять секунд."),
    ("t", "Каждый из трёх ответов Макса верен наполовину. На второй половине и ошибаются — и на экзамене, и на дороге.")))

# ---------- 1. Переход ----------
P.append('<h2 id="perehod">1. Пешеходный переход</h2>')
P.append(lq("Пешеходный переход – участок проезжей части, предназначенный для перехода пешеходов через дорогу и обозначенный дорожными знаками 5.19.1 и 5.19.2 или (и) дорожными разметками 1.14.1–1.14.2. В случае отсутствия подобных дорожных обозначений ширина пешеходного перехода определяется расстоянием между дорожными знаками 5.19.1 и 5.19.2.", "ст. 5, п. 86"))
P.append('<p>Первое слово определения — <b>участок проезжей части</b>: не «место, где ходят люди», а кусок дороги для машин с особым режимом.</p>')
P.append('<p>Обозначают его двумя способами: знаками 5.19.1 и 5.19.2 или разметкой 1.14.1–1.14.2. ' + gl("Разметка", "линии и другие обозначения на покрытии, перечисленные в приложении 2 к закону (ст. 5, п. 59); 1.14.2 — та самая «зебра»") + '. Связка <b>«или (и)»</b> означает, что достаточно любого одного способа. Краска стёрлась, а знаки стоят — переход есть. Нарисована зебра без знаков — тоже есть.</p>')
P.append('<p>От границ перехода отсчитываются запреты. Остановка запрещена</p>')
P.append(lq("на пешеходных переходах и переходах для велосипедистов, а также ближе 5 метров перед ними;", "ст. 37, п. 6 «а.а»"))
P.append('<p>(' + gl("остановка", "прекращение движения до 5 минут, дольше — только для посадки-высадки или погрузки (ст. 5, п. 11)") + '.) А в пробке на переход не въезжают вовсе: водитель не должен въезжать на него, «не убедившись заранее, что не будут вынуждены остановиться на нем» (ст. 25, п. 6).</p>')

P.append('<p>Главная обязанность водителя у перехода — пропустить пешехода. Перед светофором или регулировщиком на запрещающий сигнал водитель останавливается перед переходом или у поперечной разметки, а получив право ехать, не создаёт помех пешеходам, уже вступившим на переход (ст. 25, п. 2 «а»). Если переход не регулируется:</p>')
P.append(lq("водитель при приближении к пешеходному переходу должен надлежащим образом снизить скорость, чтобы не создать угрозу вступившим или вступающим на этот переход пешеходам, а в случае необходимости – остановиться и пропустить пешеходов.", "ст. 25, п. 2 «б»"))
P.append('<p>«Вступающим» — значит, пропускать нужно и того, кто только шагнул с тротуара. При повороте на дорогу, где нет обозначенного перехода, водитель тоже уступает пешеходам, вступившим на её проезжую часть (ст. 25, п. 3).</p>')
P.append('<h3>Странная фраза во втором предложении</h3>')
P.append('<p>Буквально второе предложение п. 86 говорит: если нет «подобных обозначений» — ни знаков, ни разметки, — ширину задают… знаки. Петля.</p>')
P.append('<p>Разгадка — в оригинале. Силу имеет грузинский текст. В первом предложении он различает <span lang="ka">ნიშნებით</span> («знаками») и <span lang="ka">მონიშვნებით</span> («разметкой»), а второе начинается так: <span lang="ka">«თუ ასეთი საგზაო მონიშვნები არ არის»</span> — «если такой дорожной <b>разметки</b> нет». Речь только о разметке; русский перевод обобщил её до «обозначений». Приложение 1 подтверждает это прочтение:</p>')
P.append(lq("При отсутствии на переходе разметки 1.14 знак 5.19.1 устанавливается на ближней границе перехода, а знак 5.19.2 – на дальней границе перехода.", "приложение 1, п. 5.19.1, 5.19.2", "annex"))
P.append('<p>Вывод: без краски переход — это полоса между знаком 5.19.1 (по приложению он стоит справа, на ближней границе) и знаком 5.19.2 (слева, на дальней).</p>')
P.append(chat(
    ("m", "То есть если зебры нет, можно встать прямо у знака?"),
    ("t", "Нет. Знак 5.19.1 и есть ближняя граница перехода. Остановка запрещена на переходе и ближе 5 метров перед ним — значит, 5 метров отсчитываешь от знака.")))
P.append(fig(fig_crossing_zebra(), "Рис. 1а. С разметкой границы видны на покрытии. Штриховка — где нельзя останавливаться (ст. 37, п. 6 «а.а»). На схеме показана только правая полоса."))
P.append(fig(fig_crossing_signs(), "Рис. 1б. Без разметки ширину перехода задают знаки: 5.19.1 справа на ближней границе, 5.19.2 слева на дальней (прил. 1, п. 5.19). Пять метров запрета отсчитываются от ближней границы."))

P.append('<h3>Где текст не сходится</h3>')
P.append('<ul class="flaws">'
         '<li>Приложение 2 описывает обе разметки — и 1.14.1, и 1.14.2 — как «нерегулируемый пешеходный переход». Разметки для перехода со светофором нет, и п. 86 светофор не называет, а ст. 25, п. 3 говорит о переходе, «обозначенного соответствующей дорожной разметкой, дорожным знаком или светофором». Зебра под светофором на практике — переход, но тексты не стыкуются.</li>'
         '<li>Знак 1.23 по тексту приложения 1 предупреждает о переходе, обозначенном знаками 5.19.1 и 5.19.2 «или (и) разметкой 1.14.1–1.14.3». Разметки 1.14.3 в приложении 2 нет — ни в русском, ни в грузинском тексте. Видимо, след старой редакции.</li>'
         '</ul>')

P.append('<h3>Миф: «у перехода обгонять нельзя никогда»</h3>')
P.append(chat(("m", "Ну хоть обгон перед зеброй точно запрещён?"),
              ("t", "В грузинском законе — не так. Читай сам.")))
P.append(lq("Транспортное средство вправе обогнать транспортное средство, приближающееся к пешеходному переходу или приостановившееся непосредственно перед этим переходом, только при достаточно сниженной скорости для обеспечения своевременной остановки в случае появления пешехода на переходе. Запрещается совершать обгон на пешеходных переходах в случае передвижения по ним пешеходов.", "ст. 34, п. 11"))
P.append('<p>' + gl("Обгон", "опережение попутных машин с выездом из своей полосы и возвращением в неё (ст. 5, п. 10)") + '. Обгон у перехода не запрещён, но с двумя условиями: скорость, на которой успеете остановиться, и пустой переход. Опаснее всего обгонять машину, <i>остановившуюся</i> перед переходом: обычно она пропускает пешехода, которого из-за неё не видно. Об этом билеты № 288, 289, 296.</p>')

# ---------- 2. Переезд ----------
P.append('<h2 id="pereezd">2. Железнодорожный переезд</h2>')
P.append(lq("Железнодорожный переезд – пересечение на одном уровне дороги с железнодорожными или трамвайными путями с независимыми полотнами.", "ст. 5, п. 58"))
P.append('<p>В определении три важных детали.</p><ol class="parts">'
         '<li><b>«На одном уровне».</b> Рельсы и дорога на одной высоте. Мост или тоннель — не переезд (неверный вариант 3 в билете № 908).</li>'
         '<li><b>«Или трамвайными».</b> Трамвай тоже может дать «железнодорожный» переезд — со всеми правилами ст. 39.</li>'
         '<li><b>«С независимыми полотнами».</b> ' + gl("Полотно", "основание, на котором лежат шпалы и рельсы") + '. Независимое — своё, отдельное от дороги. В грузинском тексте — <span lang="ka">დამოუკიდებელი ვაკისის მქონე</span>. В билете № 908 это переведено как «независимую равнину» — читайте «полотно».</li></ol>')
P.append('<p>Отсюда наше прочтение: трамвайная линия на собственном полотне, которую пересекает дорога, — это переезд. Рельсы, уложенные в асфальт посреди улицы, под определение не подходят: полотно у них общее с дорогой. Где граница (трамвайная полоса за бордюром?), закон не говорит — <span class="unsure">это неясность</span>.</p>')
P.append('<p>Что следует из статуса «переезд» — только то, что прямо написано в законе:</p><ul>'
         '<li><b>Обгон</b> запрещён «на железнодорожных переездах и ближе чем за 100 метров перед ними, кроме случая, когда движение в этих местах регулируется светофором типа, применяемого на перекрестках» (ст. 34, п. 9 «б»). Двухколёсные велосипеды, мопеды и мотоциклы без прицепа обгонять там можно (ст. 34, п. 10).</li>'
         '<li><b>Стоянка</b> запрещена «на проезжей части дороги, ближе 50 метров от железнодорожного переезда» (ст. 37, п. 7 «б»). У обгона — «перед», у стоянки — «от»: по тексту стоянка запрещена с обеих сторон. (' + gl("Стоянка", "остановка дольше 5 минут, ст. 5, п. 20") + '.)</li>'
         '<li><b>Где ждать</b>, если ехать нельзя:</li></ul>')
P.append(lq("Если движение по железнодорожному переезду запрещено, водитель останавливается перед стоп-линией, дорожным знаком 2.4 или светофором, а в случае их отсутствия – не ближе чем за 5 метров до шлагбаумов и полушлагбаумов. Если нет ни шлагбаума, ни полушлагбаума, водитель должен остановиться не ближе чем за 10 метров до ближайшего рельса.", "ст. 39, п. 3"))
P.append(chat(("a", "А если шлагбаум уже пошёл вверх — можно трогаться?"),
              ("t", "Нельзя. Въезд запрещён, если шлагбаум «закрыт, закрывается или поднимается» (ст. 39, п. 1 «б»). А при запрещающем сигнале светофора нельзя и при поднятом шлагбауме — п. 1 «в».")))
P.append(fig(fig_railway(), "Рис. 2. Зоны у переезда (не в масштабе): обгон — ст. 34, п. 9 «б»; стоянка — ст. 37, п. 7 «б»; где остановиться — ст. 39, п. 3. Предупреждающие знаки 1.1 и 1.2 вне населённого пункта ставят за 150–300 м, в населённом пункте — за 50–100 м (прил. 1, примечание «а» к разделу 1)."))
P.append(fig(fig_levels(), "Рис. 3. Переезд — только пересечение «на одном уровне» (ст. 5, п. 58). Мост или тоннель — не переезд, и запреты «у переезда» там не действуют. Другие запреты (знаки, разметка, плохая видимость) — действуют."))
P.append('<p><span class="unsure">Неясность:</span> ст. 39, п. 1 «а» требует ехать к переезду «с умеренной скоростью», но числа не даёт. Подробно правила переезда — в сериях E077–E078.</p>')

# ---------- 3. Населённый пункт ----------
P.append('<h2 id="np">3. Населённый пункт</h2>')
P.append(lq("Населенный пункт – застроенная территория, въезды на которую и выезды с которой обозначаются соответствующими дорожными знаками.", "ст. 5, п. 17"))
P.append(chat(("m", "Дома начались — значит, город, сбрасываю до 60."),
              ("t", "Притормозить при виде домов — правильно (ст. 33, п. 2). Но режим населённого пункта начинается со знака. Бывает, что дома есть, а режима нет, — и наоборот.")))
P.append('<p>В определении два признака: территория застроена <i>и</i> въезды отмечены знаками. Для водителя решает знак. В приложении 1 три разных «начала».</p>')
P.append('<p>5.23.1 — обычное начало населённого пункта, где действуют правила для населённых пунктов. Два других интереснее:</p>')
P.append(lq("5.23.2. «Начало населенного пункта» – указывает начало застроенного участка дороги, который не входит в какой-либо населенный пункт и в котором действуют правила, установленные для движения в населенных пунктах (дачные поселки, отдельно стоящие учреждения и так далее).", "приложение 1, п. 5.23.2", "annex"))
P.append(lq("5.25. «Начало населенного пункта» – указывает начало населенного пункта, в котором не действуют правила, установленные для движения в населенных пунктах.", "приложение 1, п. 5.25", "annex"))
P.append('<p>Значит, «населённый пункт» как место и его режим — разные вещи: 5.23.2 включает режим вне населённого пункта, 5.25 — населённый пункт <b>без</b> режима. Концы обозначают 5.24.1 и 5.24.2 (для 5.23.1 и 5.23.2) и 5.26 (для 5.25). Выезды отмечают «на фактической границе застройки» (прил. 1, примечание к 5.23–5.26).</p>')
P.append(signrow(SIGNS, IMG, SIGNS_CAPTION))
P.append('<p>Что меняет режим населённого пункта:</p><ul>'
         '<li><b>Скорость.</b> «…в населенных пунктах разрешается движение транспортных средств со скоростью не более 60 км/ч, а в жилых зонах – со скоростью не более 20 км/ч» (ст. 33, п. 6); знаком предел можно поднять. Вне населённых пунктов легковой категории B без прицепа — до 90 км/ч, на автомагистрали — до 110 (ст. 33, п. 7 «б.а»).</li>'
         '<li><b>Расстояния до предупреждающих знаков:</b> вне населённого пункта 150–300 м, в населённом пункте 50–100 м (прил. 1, примечание «а» к разделу 1). Дополнительные знаки 1.4.1–1.4.6 перед переездом ставят только вне населённого пункта.</li></ul>')
P.append(fig(fig_town(), "Рис. 4. Застройка может начаться раньше знака — режим всё равно включает знак начала и выключает знак конца. «5.23.x / 5.24.x» — схема, а не вид знака; как выглядит 5.23.2/5.24.2 — см. выше."))
P.append('<p><span class="unsure">Шероховатости.</span> В русском переводе примечания сказано, что «знаки 5.24.1, 5.24.2 и 5.25» ставят на выездах. В грузинском тексте на выездах стоит 5.26 — в переводе опечатка. И ст. 33, п. 7 прямо называет только «ненаселенные пункты»: то, что после знака 5.25 действуют загородные пределы скорости, — логичный вывод, но закон этого не говорит дословно.</p>')

# ---------- Ситуации ----------
P.append('<h2 id="sit">Две ситуации</h2>')
P.append('<h3>Ситуация 1. Стёртая зебра</h3>')
P.append(chat(("a", "Везу коллегу по центру. Разметки почти не видно, справа знак 5.19.1. Она просит: «Высади прямо у знака, там пусто»."),
              ("t", "Знак — ближняя граница перехода. Перед ним 5 метров, где стоять нельзя, дальше до знака 5.19.2 — сам переход. Остановиться можно раньше этих пяти метров.")))
P.append('<p>Разбор: без разметки переход — полоса между знаками (ст. 5, п. 86; прил. 1, п. 5.19), остановка запрещена на нём и ближе 5 м перед ним (ст. 37, п. 6 «а.а»). За дальним знаком «а.а» не мешает — там сказано только «перед»; но если машина закроет обзор, действует общий запрет создавать угрозу (ст. 37, п. 6 «б»).</p>')
P.append('<h3>Ситуация 2. Очередь у переезда</h3>')
P.append(chat(("m", "Загород, шлагбаум закрыт, передо мной пять машин. Встречка пустая — объеду и встану первым."),
              ("t", "Это прямо запрещено. И когда шлагбаум поднимется, посмотри, есть ли место за путями.")))
P.append('<p>Разбор: на переезде запрещается «объезжать с выездом на полосу встречного движения транспортные средства, стоящие перед железнодорожным переездом» (ст. 39, п. 2 «а»). Обгон ближе 100 м — тоже (ст. 34, п. 9 «б»). После открытия нельзя въезжать, «если заранее не убедится, что не будет вынужден остановиться на нем» (ст. 39, п. 1 «д»): пробка за путями — ждите перед переездом.</p>')
P.append('<p class="note info">Дальше — билеты из экзаменационной базы. № 908 и № 891 — прямо об определениях этого выпуска. Остальные — о поведении у перехода, на переезде и о скорости в населённом пункте. После билетов — наши вопросы к уроку (их нет в базе билетов).</p>')

P.append("<!--AFTER-TICKETS-->")
P.append(chat(("a", "Итого. Переход без краски — между знаками, и 5 метров перед ним стоять нельзя. Переезд — только на одном уровне, трамвай тоже считается. Населённый пункт начинается со знака, а не с домов."),
              ("m", "И обгонять у зебры можно — но медленно и если на ней никого. Ладно, наполовину я был прав."),
              ("t", "На этом словарь дорог закончен. Дальше — кто по ним движется: участники и транспорт.")))

